// Generated by Automated Quality Gate; review before merging.
const {
  add,
  subtract,
  multiply,
  divide,
  calculatePercentage,
  modulo,
  absoluteDifference
} = require('../../src/math');

describe('math utility functions', () => {
  describe('input validation', () => {
    const invalidInputs = ['1', null, undefined, NaN, Infinity, -Infinity];
    const functions = [add, subtract, multiply, divide, calculatePercentage, modulo, absoluteDifference];

    functions.forEach((fn) => {
      test(`${fn.name} should throw TypeError for non-number inputs`, () => {
        expect(() => fn('a', 1)).toThrow(TypeError);
        expect(() => fn(1, null)).toThrow('Inputs must be valid numbers');
      });

      test(`${fn.name} should throw TypeError for non-finite inputs`, () => {
        expect(() => fn(Infinity, 1)).toThrow('Inputs must be finite numbers');
        expect(() => fn(1, -Infinity)).toThrow(TypeError);
      });
    });
  });

  describe('add', () => {
    test('should add positive and negative numbers correctly', () => {
      expect(add(2, 3)).toBe(5);
      expect(add(-1, -1)).toBe(-2);
      expect(add(0, 0)).toBe(0);
    });
  });

  describe('subtract', () => {
    test('should subtract and normalize -0', () => {
      expect(subtract(5, 10)).toBe(-5);
      const result = subtract(1, 1);
      expect(result).toBe(0);
      expect(Object.is(result, -0)).toBe(false);
    });
  });

  describe('multiply', () => {
    test('should multiply and normalize -0', () => {
      expect(multiply(-2, 0)).toBe(0);
      expect(Object.is(multiply(-2, 0), -0)).toBe(false);
    });
  });

  describe('divide', () => {
    test('should divide correctly', () => {
      expect(divide(10, 2)).toBe(5);
    });

    test('should throw error on division by zero', () => {
      expect(() => divide(10, 0)).toThrow('Cannot divide by zero');
      expect(() => divide(10, -0)).toThrow('Cannot divide by zero');
    });
  });

  describe('calculatePercentage', () => {
    test('should return 0 when total is 0', () => {
      expect(calculatePercentage(50, 0)).toBe(0);
    });

    test('should calculate correct percentage', () => {
      expect(calculatePercentage(50, 200)).toBe(25);
    });
  });

  describe('modulo', () => {
    test('should handle modulo with negative numbers', () => {
      expect(modulo(-7, 4)).toBe(1);
      expect(modulo(7, -4)).toBe(-1); // JS % behavior handled by formula
    });

    test('should throw error on modulo by zero', () => {
      expect(() => modulo(10, 0)).toThrow('Cannot modulo by zero');
    });
  });

  describe('absoluteDifference', () => {
    test('should return absolute difference', () => {
      expect(absoluteDifference(10, 2)).toBe(8);
      expect(absoluteDifference(2, 10)).toBe(8);
    });
  });
});
